  "ada/check_conditional_information.py": """"Check the conditional-information decomposition on synthetic SPD models."""
import json
from pathlib import Path
import numpy as np

def logdet(matrix):
    sign, value = np.linalg.slogdet(matrix)
    assert sign > 0
    return value

def information(covariance, rank_x):
    return .5 * (logdet(covariance[:rank_x, :rank_x])
                 + logdet(covariance[rank_x:, rank_x:]) - logdet(covariance))

def mixed(values):
    return values[3] + values[0] - values[1] - values[2]

def check(K, U, V, retained, a, b):
    W = np.column_stack((U, V))
    noise = np.diag([1/a]*U.shape[1] + [1/b]*V.shape[1])
    contact_cov = W.T @ np.linalg.solve(K, W) + noise
    D = K[retained:, retained:]
    omitted_W = W[retained:]
    conditional_cov = omitted_W.T @ np.linalg.solve(D, omitted_W) + noise
    # Independent conditional covariance calculation from the joint law (z,x,y).
    full_cov = np.linalg.solve(K, np.eye(len(K)))
    Cz = full_cov[:retained, :retained]
    Czc = full_cov[:retained] @ W
    conditional_direct = contact_cov-Czc.T @ np.linalg.solve(Cz, Czc)
    np.testing.assert_allclose(conditional_cov, conditional_direct, atol=2e-12)
    I = information(contact_cov, U.shape[1])
    Ic = information(conditional_cov, U.shape[1])
    corners = [K, K+a*U@U.T, K+b*V@V.T, K+a*U@U.T+b*V@V.T]
    schurs, omitted = [], []
    for corner in corners:
        A = corner[:retained, :retained]
        B = corner[:retained, retained:]
        Dcorner = corner[retained:, retained:]
        schurs.append(A-B @ np.linalg.solve(Dcorner, B.T))
        omitted.append(Dcorner)
    full_cycle = .5*mixed([logdet(c) for c in corners])
    retained_cycle = .5*mixed([logdet(s) for s in schurs])
    omitted_cycle = .5*mixed([logdet(d) for d in omitted])
    residual = max(abs(full_cycle+I), abs(omitted_cycle+Ic),
                   abs(retained_cycle-(Ic-I)))
    assert residual < 2e-11
    return dict(information_nats=I, conditional_information_nats=Ic,
                full_cycle_kBT=full_cycle, retained_cycle_kBT=retained_cycle,
                omitted_cycle_kBT=omitted_cycle, max_identity_residual=residual)

K = np.array([[2., 1.], [1., 2.]])
U = np.array([[1.], [1.]])
V = np.array([[0.], [1.]])
witness = check(K, U, V, 1, 1., 1.)
assert witness['retained_cycle_kBT'] > 0
control = check(K, U, np.array([[1.], [0.]]), 1, 1., 1.)
assert abs(control['conditional_information_nats']) < 1e-14
assert control['retained_cycle_kBT'] <= 0

rng = np.random.default_rng(824105)
checks = []
for _ in range(120):
    X = rng.normal(size=(7, 7))
    K = X @ X.T + np.eye(7)
    U, V = rng.normal(size=(7, 2)), rng.normal(size=(7, 3))
    checks.append(check(K, U, V, 3, .7, 1.3))
result = dict(scope='Synthetic fixed-space Gaussian models only; not molecular evidence',
              witness=witness, one_retained_only_control=control,
              random_checks=len(checks),
              max_identity_residual=max(c['max_identity_residual'] for c in checks))
Path(__file__).with_name('conditional-information-results.json').write_text(
    json.dumps(result, indent=2)+'\n')
print(json.dumps(result))
