  "emmy/check_marginal_bounds.py": """"Fixed-space Gaussian Schur checks; no molecular data or partner writes."""
import json
from pathlib import Path
import numpy as np

def ld(a):
    sign, value = np.linalg.slogdet(a)
    assert sign > 0
    return value

def cyc(v):
    return .5 * (v[3] + v[0] - v[1] - v[2])

def schur(k, n):
    a, b, d = k[:n, :n], k[:n, n:], k[n:, n:]
    return a - b @ np.linalg.solve(d, b.T)

def corners(k, u, v):
    return [k, k+u@u.T, k+v@v.T, k+u@u.T+v@v.T]

def invsqrt(a):
    w, z = np.linalg.eigh(a)
    assert min(w) > 0
    return (z / np.sqrt(w)) @ z.T

rng = np.random.default_rng(8107)
rows = []
for case in range(24):
    r = rng.normal(size=(7, 7))
    k = r@r.T + np.eye(7)
    u, v = rng.normal(size=(7, 2)), rng.normal(size=(7, 2))
    a, b, d = k[:3, :3], k[:3, 3:], k[3:, 3:]
    w = np.column_stack((u, v))
    wx, wz = w[:3], w[3:]
    residual = wx - b @ np.linalg.solve(d, wz)
    predicted = schur(k, 3) + residual @ np.linalg.solve(
        np.eye(4)+wz.T@np.linalg.solve(d, wz), residual.T)
    ks = corners(k, u, v)
    ss, ds = [schur(c, 3) for c in ks], [c[3:, 3:] for c in ks]
    full, retained, omitted = [cyc([ld(c) for c in cs]) for cs in (ks, ss, ds)]
    p = u[3:].T@np.linalg.solve(d, u[3:])
    q = v[3:].T@np.linalg.solve(d, v[3:])
    cross = u[3:].T@np.linalg.solve(d, v[3:])
    svals = np.linalg.svd(invsqrt(p)@cross@invsqrt(q), compute_uv=False)
    assert max(svals) < 1
    lower = .5*np.log1p(-svals*svals).sum()
    assert lower-1e-12 <= omitted <= 1e-12
    assert retained+lower-1e-12 <= full <= min(0, retained)+1e-12
    assert abs(full-retained-omitted) < 1e-12
    schur_error = np.max(np.abs(predicted-ss[3]))
    assert schur_error < 1e-12
    # Only U touches omitted coordinates; V is retained-only.
    vr = v.copy()
    vr[3:] = 0
    kr = corners(k, u, vr)
    sr = [schur(c, 3) for c in kr]
    additive_error = np.max(np.abs(sr[3]+sr[0]-sr[1]-sr[2]))
    cycle_error = abs(cyc([ld(c) for c in kr])-cyc([ld(c) for c in sr]))
    assert additive_error < 1e-12 and cycle_error < 1e-12
    # Both bundles omitted, but orthogonal in conditional D^{-1} metric.
    vo = v.copy()
    vo[3:] -= u[3:] @ np.linalg.solve(p, u[3:].T@np.linalg.solve(d, vo[3:]))
    orthogonal_cross = np.max(np.abs(u[3:].T@np.linalg.solve(d, vo[3:])))
    ko = corners(k, u, vo)
    so = [schur(c, 3) for c in ko]
    orthogonal_additive_error = np.max(np.abs(so[3]+so[0]-so[1]-so[2]))
    orthogonal_cycle_error = abs(cyc([ld(c) for c in ko])-cyc([ld(c) for c in so]))
    assert max(orthogonal_cross, orthogonal_additive_error, orthogonal_cycle_error) < 1e-12
    rows.append(dict(case=case, full_kBT=full, retained_kBT=retained,
                     omitted_kBT=omitted, omitted_saturation_kBT=lower,
                     schur_error=schur_error, one_bundle_additive_error=additive_error,
                     one_bundle_cycle_error=cycle_error,
                     orthogonal_omitted_cross=orthogonal_cross,
                     orthogonal_additive_error=orthogonal_additive_error,
                     orthogonal_cycle_error=orthogonal_cycle_error))

# Same retained covariance quartet, arbitrarily negative hidden spring cycle.
hidden = []
for t in (0., 1., 10., 1e3, 1e6):
    k = np.eye(2)
    u = np.diag([1., np.sqrt(t)])
    v = np.diag([2., np.sqrt(t)])
    ks = corners(k, u, v)
    covariance = [float(np.linalg.inv(c)[0, 0]) for c in ks]
    assert np.allclose(covariance, [1., .5, .2, 1/6])
    retained = .5*np.log(6/10)
    omitted = .5*(np.log1p(2*t)-2*np.log1p(t))
    assert abs(cyc([ld(c) for c in ks])-retained-omitted) < 1e-12
    hidden.append(dict(t=t, retained_covariance=covariance, retained_kBT=retained,
                       omitted_kBT=omitted, full_kBT=retained+omitted))

result = dict(seed=8107, random_checks=rows, hidden_extension=hidden,
              max_schur_error=max(r['schur_error'] for r in rows),
              max_one_bundle_additive_error=max(r['one_bundle_additive_error'] for r in rows),
              max_one_bundle_cycle_error=max(r['one_bundle_cycle_error'] for r in rows),
              max_orthogonal_additive_error=max(r['orthogonal_additive_error'] for r in rows),
              max_orthogonal_cycle_error=max(r['orthogonal_cycle_error'] for r in rows))
Path(__file__).with_name('marginal-bounds-results.json').write_text(json.dumps(result, indent=2)+'\n')
print(json.dumps({k:v for k,v in result.items() if k not in ('random_checks','hidden_extension')}))
